+/** Records a successful data-changing API request. */
+export function recordAudit(store, { time, name, method, path, status }) {
+  store.data.audit.push({ time, name, method, path, status });
+}
+
+/** Lists audit entries newest first, including reverse insertion order for ties. */
+export function listAudit(store) {
+  return [...store.data.audit].reverse().sort((a, b) => b.time.localeCompare(a.time));
+}
